<template>
 <div class="rest-room">
  <header class="room-heading"><div><h1>互动休息室</h1><p>暂时放下手边的事，给自己一点休息时间。</p></div><div class="heading-actions"><span class="today-count">今日已完成 <strong>{{ todayCompleted }}</strong> 次</span><button class="voice-button" type="button" :aria-pressed="voiceEnabled" @click="toggleVoice">{{ voiceEnabled ? '关闭浏览器语音' : '开启浏览器语音' }}</button></div></header>
  <div v-if="serviceError" class="room-notice" role="alert"><span>{{ serviceError }}</span><button type="button" @click="loadInitial">重新连接</button></div>
  <main class="room-columns">
   <section class="practice-panel" aria-label="休息项目">
    <div class="project-strip" role="radiogroup" aria-label="选择休息项目"><button v-for="project in projects" :key="project.id" type="button" role="radio" :aria-checked="selectedProject === project.id" :disabled="Boolean(active)" :class="['project-choice',{selected:selectedProject === project.id}]" @click="selectedProject=project.id"><svg viewBox="0 0 24 24" aria-hidden="true"><template v-if="project.id==='breathing'"><path d="M3 8h12c5 0 5-6 1-6M3 12h16c4 0 4 6 0 6M3 16h8c4 0 4 6 0 6"/></template><template v-else-if="project.id==='eyes'"><path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></template><template v-else><circle cx="12" cy="4" r="2"/><path d="M5 9l7 2 7-2M12 11v6m0-2-5 6m5-6 5 6"/></template></svg><span><strong>{{ project.title }}</strong><small>{{ project.duration_seconds }} 秒</small></span></button></div>
    <div :class="['practice-stage',`phase-${active?.phase || 'idle'}`]">
     <div class="stage-status"><span class="status-dot"/>{{ phaseLabel }}</div>
     <div class="breath-orbit" :class="{moving:active?.phase==='running',finished:active?.phase==='awaiting_confirmation'}"><div class="orbit-line orbit-outer"/><div class="orbit-line orbit-inner"/><div class="breath-core" :style="orbStyle"><svg v-if="active?.phase==='awaiting_confirmation'" viewBox="0 0 48 48" aria-hidden="true"><path d="M16 21 25 8c3 0 4 2 3 6l-2 6h12c3 0 4 3 3 6l-4 13H16Zm-8 1h8v18H8Z"/></svg><span v-else>{{ centreText }}</span></div></div>
     <h2>{{ stageTitle }}</h2><p class="stage-description">{{ stageDescription }}</p><div class="time-display" aria-label="剩余时间">{{ timeLabel }}</div>
     <div v-if="active" class="session-track" role="progressbar" :aria-valuenow="Math.round(sessionProgress*100)" aria-valuemin="0" aria-valuemax="100" aria-label="休息进度"><span :style="{width:`${sessionProgress*100}%`}"/></div>
     <div class="practice-actions"><button v-if="!active" class="button-primary" type="button" :disabled="!serviceReady||actionBusy" @click="begin">{{ actionBusy ? '正在开始…' : '开始休息' }}</button><template v-else-if="active.phase==='running'||active.phase==='paused'"><button class="button-primary" type="button" :disabled="actionBusy||!serviceReady" @click="act(active.phase==='paused'?'resume':'pause')">{{ active.phase==='paused'?'继续休息':'暂停' }}</button><button class="button-secondary" type="button" :disabled="actionBusy||!serviceReady" @click="act('cancel')">结束本次</button></template><button v-else-if="active.phase==='awaiting_confirmation'" class="button-primary" type="button" :disabled="actionBusy||!serviceReady" @click="act('finish')">{{ actionBusy?'正在保存…':'确认完成，保存记录' }}</button></div>
     <p class="stage-footnote">{{ active?.phase==='awaiting_confirmation'?'也可以竖起大拇指，保持约 1 秒完成确认。':active?'按自己的节奏进行，暂停后不计入休息时长。':'选好项目后，也可以张开手掌，保持约 1 秒开始。' }}</p>
    </div>
    <div v-if="latestCompletion&&!active" class="completion-note" role="status"><span class="completion-check">✓</span><div><strong>{{ latestCompletion.title }}已完成</strong><span>这次休息已保存到下方记录。</span></div></div>
   </section>
   <aside class="gesture-panel" aria-label="手势控制">
    <div class="panel-title"><h2>用手势和小智互动</h2><span :class="['recognition-tag',{enabled:gestureEnabled&&!cameraError&&!gestureLoading}]">{{ gestureLoading?'加载模型中':gestureEnabled&&!cameraError?'识别已开启':'未开启' }}</span></div>
    <p class="panel-description">先选择摄像头，再开启手势。按钮操作始终可用。</p>
    <label class="source-label" for="rest-camera">摄像头来源</label><div class="source-control"><select id="rest-camera" v-model="cameraSource" :disabled="gestureEnabled||gestureLoading"><option value="local">本机摄像头</option><option value="rtsp">RTSP 摄像头</option><option v-for="device in devices" :key="device.device_id" :value="`xiaozhi:${device.device_id}`">{{ device.name||device.device_name||device.device_id }}{{ device.online?' · 在线':' · 离线' }}</option></select><button type="button" aria-label="刷新小智设备" :disabled="deviceLoading||gestureEnabled" @click="loadDevices">↻</button></div>
    <p v-if="deviceError" class="device-note">{{ deviceError }} <router-link to="/xiaozhi/devices">设备管理</router-link></p>
    <div class="camera-preview" :class="{live:gestureEnabled&&hasFrame}"><canvas ref="previewCanvas" width="640" height="480" aria-label="摄像头手势预览"/><div v-if="!gestureEnabled||!hasFrame" class="camera-empty"><svg viewBox="0 0 48 48" aria-hidden="true"><rect x="7" y="13" width="25" height="23" rx="4"/><path d="m32 20 10-5v19l-10-5Z"/></svg><strong>{{ gestureLoading?'正在准备本地识别模型':gestureEnabled?'等待摄像头画面':'手势识别尚未开启' }}</strong><span>{{ gestureLoading?'首次加载可能需要几秒钟':'此页面不保存摄像头画面' }}</span></div></div>
    <div v-if="cameraError" class="camera-error" role="status">{{ cameraError }}</div>
    <div class="gesture-live" aria-live="polite"><span>{{ gestureMessage }}</span><div class="hold-track"><i :style="{width:`${holdProgress*100}%`}"/></div></div>
    <button class="gesture-toggle" type="button" :aria-pressed="gestureEnabled" :disabled="gestureLoading&&!gestureEnabled" @click="gestureEnabled?stopGestures():enableGestures()">{{ gestureEnabled?'关闭手势识别':'开启手势识别' }}</button>
    <div class="gesture-instructions"><div><span class="hand-symbol" aria-hidden="true">✋</span><p><strong>张开手掌</strong><small>准备好后，开始所选项目</small></p></div><div><span class="hand-symbol" aria-hidden="true">👍</span><p><strong>竖起大拇指</strong><small>倒计时结束后，确认并保存</small></p></div></div><p class="privacy-note">手心朝向镜头，五指完整进入画面，保持约 1 秒。选择小智后只使用该设备画面。</p>
   </aside>
  </main>
  <section class="records-panel" aria-label="我的休息记录"><div class="records-heading"><div><h2>我的休息记录</h2><p>每一段完成的休息，都值得被记住。</p></div><button type="button" :disabled="refreshing" @click="refreshState">刷新记录</button></div><div v-if="!records.length" class="records-empty">完成第一次休息后，你的记录卡片会出现在这里。</div><div v-else class="record-grid"><article v-for="record in records" :key="record.id" class="record-card"><div class="record-card-top"><strong>{{ record.title }}</strong><span>已完成</span></div><p>{{ formatDate(record.completed_at) }}</p><div class="record-details"><span>{{ record.duration_seconds }} 秒</span><span>{{ record.completed_by==='gesture'?'手势确认':'按钮确认' }}</span></div><small>{{ record.device_label||sourceLabel(record.source) }}</small></article></div></section>
 </div>
</template>
<script setup>
import { ref, computed, onMounted, onBeforeUnmount } from 'vue'
import { restCatalog, restState, startRest, restAction, restDevices, restFrame } from '@/api/interactiveRest'
import { createRestRecognizer, GestureGate, interpretGesture, eligibleRestGesture } from '@/utils/restGestures'
const defaults = [
 { id:'breathing',title:'呼吸放松',description:'跟随圆环，缓缓吸气与呼气。',duration_seconds:60,prompt:'跟随圆环，按舒适的节奏呼吸。' },
 { id:'eyes',title:'远眺休息',description:'暂时离开屏幕，看看远处。',duration_seconds:60,prompt:'让视线离开屏幕，看看远处。' },
 { id:'stretch',title:'肩颈放松',description:'轻轻活动肩膀，舒展一下。',duration_seconds:90,prompt:'放松肩膀，轻轻舒展。' }
]
const projects=ref(defaults),selectedProject=ref('breathing'),active=ref(null),records=ref([]),todayCompleted=ref(0),latestCompletion=ref(null)
const serviceError=ref(''),serviceReady=ref(false),refreshing=ref(false),actionBusy=ref(false),tick=ref(performance.now())
const devices=ref([]),deviceLoading=ref(false),deviceError=ref(''),cameraSource=ref('local'),previewCanvas=ref(null)
const gestureEnabled=ref(false),gestureLoading=ref(false),cameraError=ref(''),hasFrame=ref(false),gestureMessage=ref('开启后，张开手掌即可开始'),holdProgress=ref(0),voiceEnabled=ref(false)
let mounted=false,pollTimer=null,clockTimer=null,snapshotAt=performance.now(),stateRevision=0,lastPhase=null,recognizer=null,frameTimer=null,cameraAbort=null,cameraRun=0,speaking=false,lastFrameKey='',lastFreshAt=0
const gate=new GestureGate({ scoreThreshold: 0.6 })
const selected=computed(()=>projects.value.find(p=>p.id===(active.value?.project_id||selectedProject.value))||defaults[0])
const elapsed=computed(()=>Math.min(active.value?.duration_seconds||selected.value.duration_seconds,Math.max(0,Number(active.value?.elapsed_seconds||0)+(active.value?.phase==='running'&&serviceReady.value?Math.max(0,tick.value-snapshotAt)/1000:0))))
const remaining=computed(()=>Math.max(0,(active.value?.duration_seconds||selected.value.duration_seconds)-elapsed.value))
const timeLabel=computed(()=>`${String(Math.floor(Math.ceil(remaining.value)/60)).padStart(2,'0')}:${String(Math.ceil(remaining.value)%60).padStart(2,'0')}`)
const sessionProgress=computed(()=>active.value?elapsed.value/active.value.duration_seconds:0)
const phaseLabel=computed(()=>({running:'休息进行中',paused:'已暂停',awaiting_confirmation:'等待确认完成'}[active.value?.phase]||'准备开始'))
const centreText=computed(()=>!active.value?'慢下来':active.value.phase==='paused'?'暂停中':active.value.project_id==='breathing'?(Math.floor(elapsed.value/4)%2?'缓缓呼气':'缓缓吸气'):active.value.project_id==='eyes'?'看看远处':'舒展一下')
const stageTitle=computed(()=>active.value?.phase==='awaiting_confirmation'?'这段休息，送自己一个赞':active.value?selected.value.title:'准备好，休息一下')
const stageDescription=computed(()=>active.value?.phase==='awaiting_confirmation'?'倒计时已结束，确认后生成本次休息记录。':selected.value.description)
const orbStyle=computed(()=>({transform:`scale(${active.value?.phase==='running'&&active.value.project_id==='breathing'?0.92+(1-Math.cos(elapsed.value*Math.PI/4))*0.09:1})`}))
function sourceLabel(source){return source==='local'?'本机摄像头':source==='rtsp'?'RTSP 摄像头':devices.value.find(d=>`xiaozhi:${d.device_id}`===source)?.name||'小智摄像头'}
function formatDate(value){if(!value)return '';const d=new Date(typeof value==='number'?value*1000:value);return Number.isNaN(d.getTime())?'':d.toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}
function speak(text){if(!voiceEnabled.value||!('speechSynthesis'in window))return;if(speaking)window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='zh-CN';u.rate=0.9;speaking=true;u.onend=()=>{speaking=false};window.speechSynthesis.speak(u)}
function toggleVoice(){if(!('speechSynthesis'in window)){serviceError.value='当前浏览器不支持语音引导，仍可使用页面提示';return}voiceEnabled.value=!voiceEnabled.value;if(voiceEnabled.value)speak('浏览器语音引导已开启。');else if(speaking){window.speechSynthesis.cancel();speaking=false}}
function applySession(next){
 if(next?.phase==='awaiting_confirmation'&&lastPhase!=='awaiting_confirmation')speak('休息时间到了。竖起大拇指，或者点击按钮，确认完成。')
 lastPhase=next?.phase||null
 active.value=next
 if(next)selectedProject.value=next.project_id
 snapshotAt=performance.now()
 tick.value=snapshotAt
 serviceReady.value=true
 serviceError.value=''
}
function applyState(data){
 applySession(data.active||null)
 records.value=data.records||[]
 todayCompleted.value=data.today_completed||0
}
async function refreshState(){if(!mounted||refreshing.value||actionBusy.value)return;const revision=stateRevision;refreshing.value=true;try{const data=await restState();if(mounted&&revision===stateRevision)applyState(data)}catch(e){if(mounted&&revision===stateRevision){serviceReady.value=false;serviceError.value=e.message}}finally{refreshing.value=false}}
async function loadInitial(){try{const data=await restCatalog();if(mounted&&data.projects?.length)projects.value=data.projects}catch(e){if(mounted)serviceError.value=e.message}await refreshState()}
async function poll(){await refreshState();if(mounted)pollTimer=setTimeout(poll,2500)}
async function begin(){
 if(active.value||actionBusy.value||!serviceReady.value)return
 actionBusy.value=true
 ++stateRevision
 try{
  const {session}=await startRest({project_id:selectedProject.value,source:cameraSource.value,device_label:sourceLabel(cameraSource.value)})
  if(!mounted)return
  applySession(session)
  latestCompletion.value=null
  if(session.phase==='running'){
   speak(`${selected.value.title}开始了。${selected.value.prompt||selected.value.description}`)
   gestureMessage.value='休息已开始，放下手掌就好'
  }
 }catch(e){
  if(mounted)serviceError.value=e.message
 }finally{
  actionBusy.value=false
 }
}
async function act(action,method='button'){
 if(!active.value||actionBusy.value||!serviceReady.value)return
 actionBusy.value=true
 ++stateRevision
 try{
  const {session}=await restAction(active.value.id,{action,method})
  if(!mounted)return
  const completed=session.phase==='completed'
  applySession(completed||session.phase==='cancelled'?null:session)
  if(completed){
   records.value=[session,...records.value.filter(record=>record.id!==session.id)].slice(0,20)
   latestCompletion.value=session
   speak('完成了，你的休息记录已经保存。')
   gestureMessage.value='已完成并保存，给自己一点鼓励'
  }else if(action==='pause'&&session.phase==='paused'&&speaking){
   window.speechSynthesis.cancel()
   speaking=false
  }else if(action==='resume'&&session.phase==='running'){
   speak('继续休息，按自己的节奏进行。')
  }
 }catch(e){
  if(mounted)serviceError.value=e.message
 }finally{
  actionBusy.value=false
 }
}
async function loadDevices(){deviceLoading.value=true;try{const data=await restDevices();if(mounted){devices.value=(data.devices||[]).filter(d=>d.device_id);deviceError.value=devices.value.length?'':'尚未发现小智设备。'}}catch{if(mounted)deviceError.value='小智服务暂未连接，可使用本机摄像头。'}finally{deviceLoading.value=false}}
function drawHand(ctx,points,w,h){if(!Array.isArray(points)||points.length<21)return;ctx.lineWidth=2;ctx.strokeStyle='#63e3c2';for(const chain of [[0,1,2,3,4],[0,5,6,7,8],[5,9,10,11,12],[9,13,14,15,16],[13,17,18,19,20],[0,17]]){ctx.beginPath();chain.forEach((n,i)=>{const p=points[n];if(i)ctx.lineTo(p.x*w,p.y*h);else ctx.moveTo(p.x*w,p.y*h)});ctx.stroke()}ctx.fillStyle='#fff';for(const p of points){ctx.beginPath();ctx.arc(p.x*w,p.y*h,2.3,0,Math.PI*2);ctx.fill()}}
async function enableGestures(){if(gestureEnabled.value||gestureLoading.value)return;const run=++cameraRun;gestureEnabled.value=true;gestureLoading.value=true;cameraError.value='';hasFrame.value=false;gate.reset();lastFrameKey='';lastFreshAt=performance.now();try{const model=await createRestRecognizer();if(!mounted||run!==cameraRun){model.close();return}recognizer=model;gestureLoading.value=false;await frameLoop(run)}catch(e){if(run===cameraRun){cameraError.value=e.message;gestureEnabled.value=false;gestureLoading.value=false;recognizer?.close();recognizer=null}}}
function stopGestures(){++cameraRun;gestureEnabled.value=false;gestureLoading.value=false;clearTimeout(frameTimer);cameraAbort?.abort();cameraAbort=null;recognizer?.close();recognizer=null;hasFrame.value=false;holdProgress.value=0;gate.reset();gestureMessage.value='手势已关闭，仍可使用按钮操作';cameraError.value='';const canvas=previewCanvas.value;canvas?.getContext('2d')?.clearRect(0,0,canvas.width,canvas.height)}
async function frameLoop(run){if(!mounted||run!==cameraRun||!recognizer)return;let delay=280,bitmap=null;cameraAbort=new AbortController();try{const frame=await restFrame(cameraSource.value,cameraAbort.signal);if(run!==cameraRun||!mounted)return;if(!frame.capturedAt||Date.now()/1000-frame.capturedAt>3)throw new Error('摄像头画面已过期，正在等待新画面');const hash=await crypto.subtle.digest('SHA-256',await frame.blob.arrayBuffer());const key=`${cameraSource.value}:${Array.from(new Uint8Array(hash),b=>b.toString(16).padStart(2,'0')).join('')}`;if(key===lastFrameKey){if(performance.now()-lastFreshAt>3500)throw new Error('画面暂未更新，请检查摄像头');return}lastFrameKey=key;lastFreshAt=performance.now();bitmap=await createImageBitmap(frame.blob);if(run!==cameraRun||!mounted||!recognizer)return;const canvas=previewCanvas.value;if(!canvas)return;const ratio=Math.min(1,640/bitmap.width);canvas.width=Math.round(bitmap.width*ratio);canvas.height=Math.round(bitmap.height*ratio);const ctx=canvas.getContext('2d');ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);const now=performance.now();const parsed=interpretGesture(recognizer.recognizeForVideo(canvas,now));drawHand(ctx,parsed.landmarks,canvas.width,canvas.height);const eligibleLabel=eligibleRestGesture(active.value?.phase,parsed.label);const held=gate.update(eligibleLabel,parsed.score,now,key);holdProgress.value=held.progress;hasFrame.value=true;cameraError.value='';gestureMessage.value=parsed.label==='open_palm'?(active.value?'已识别手掌，正在休息中':'识别到手掌，请保持片刻'):parsed.label==='thumb_up'?(active.value?.phase==='awaiting_confirmation'?'识别到点赞，请保持片刻':'点赞确认会在休息结束后开启'):active.value?.phase==='awaiting_confirmation'?'竖起大拇指，确认完成':'张开手掌，开始所选项目';if(held.trigger==='open_palm'&&!active.value)await begin();if(held.trigger==='thumb_up'&&active.value?.phase==='awaiting_confirmation')await act('finish','gesture')}catch(e){if(mounted&&run===cameraRun){cameraError.value=e.message;holdProgress.value=0;gate.reset();delay=1800}}finally{bitmap?.close();if(mounted&&run===cameraRun&&gestureEnabled.value)frameTimer=setTimeout(()=>frameLoop(run),delay)}}
onMounted(async()=>{mounted=true;clockTimer=setInterval(()=>{tick.value=performance.now()},200);await loadInitial();loadDevices();if(mounted)pollTimer=setTimeout(poll,2500)})
onBeforeUnmount(()=>{mounted=false;clearTimeout(pollTimer);clearInterval(clockTimer);stopGestures();if(speaking)window.speechSynthesis.cancel()})
</script>
<style scoped>
.rest-room{--blue:#3263d8;--purple:#7360b8;--ink:#20364b;--muted:#75849a;--line:#e0e7f0;--mint:#2aa68b;max-width:1600px;margin:auto;padding:26px 30px 40px;color:var(--ink);font-family:'Microsoft YaHei','PingFang SC',sans-serif;background:#f4f7fb;min-height:calc(100vh - 84px)}.room-heading{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:24px}.room-heading h1{font-size:27px;letter-spacing:.02em;margin:0 0 9px;font-weight:650}.room-heading p{font-size:14px;color:var(--muted);margin:0;line-height:1.6}.heading-actions{display:flex;align-items:center;gap:20px}.today-count{font-size:13px;color:#65788f;white-space:nowrap}.today-count strong{font-size:23px;color:var(--blue);padding:0 6px;font-variant-numeric:tabular-nums}.voice-button,.records-heading button{border:1px solid #d8e2f0;background:#fff;color:#466288;padding:9px 12px;border-radius:6px;cursor:pointer;font-size:12px}.voice-button[aria-pressed=true]{background:#eaf1ff;color:var(--blue);border-color:#9cb6ef}
.room-columns{display:grid;grid-template-columns:minmax(460px,1.55fr) minmax(325px,1fr);gap:24px;align-items:start}.practice-panel{background:#fff;border:1px solid var(--line);border-radius:12px;overflow:hidden}.project-strip{display:grid;grid-template-columns:repeat(3,1fr);padding:16px;gap:10px;border-bottom:1px solid #e8edf5}.project-choice{display:flex;align-items:center;justify-content:center;gap:10px;border:1px solid transparent;background:#f5f7fb;color:#61758e;border-radius:7px;padding:12px 6px;cursor:pointer;text-align:left;transition:background .18s}.project-choice svg{width:25px;height:25px;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}.project-choice strong{font-size:14px;font-weight:600;display:block;margin-bottom:4px}.project-choice small{font-size:11px;display:block;color:#8a98ab}.project-choice.selected{border-color:#bdcdf1;color:var(--blue);background:#edf3ff}.project-choice:disabled{cursor:default;opacity:1}.practice-stage{text-align:center;position:relative;padding:24px 20px 22px;background:radial-gradient(ellipse at 50% 36%,#f4f6ff 0,#fff 58%)}.stage-status{font-size:12px;color:#73819a;display:flex;justify-content:center;align-items:center;gap:7px}.status-dot{width:6px;height:6px;background:#9baabd;border-radius:50%}.phase-running .status-dot{background:var(--mint)}.phase-awaiting_confirmation .status-dot{background:var(--purple)}
